function v(id,labelEn,labelAr,defaultValue="",constraints={}){return Object.freeze({id,labelEn,labelAr,defaultValue,...constraints})}
function pf(id,titleEn,titleAr,formulaEn,formulaAr,calcExpression,variables,unit="",rules=[]){
  return Object.freeze({id,titleEn,titleAr,formulaEn,formulaAr,calcExpression,variables:Object.freeze(variables),unit,rules:Object.freeze(rules)});
}
function tpf(topicEn,topicAr,id,titleEn,titleAr,formulaEn,formulaAr,calcExpression,variables,unit="",rules=[]){
  return Object.freeze({...pf(id,titleEn,titleAr,formulaEn,formulaAr,calcExpression,variables,unit,rules),topicEn,topicAr});
}
function hpf(topicEn,topicAr,id,titleEn,titleAr,formulaEn,formulaAr,calcExpression,variables,unit="",rules=[]){
  return tpf(topicEn,topicAr,id,titleEn,titleAr,formulaEn,formulaAr,calcExpression,variables,unit,rules);
}
function hpr(topicEn,topicAr,id,titleEn,titleAr,formulaEn,formulaAr,noteEn){
  return Object.freeze({id,titleEn,titleAr,formulaEn,formulaAr,calcExpression:null,variables:Object.freeze([]),unit:"",rules:Object.freeze([]),topicEn,topicAr,noteEn});
}

export function getProfessionalLibrary(id){return PROFESSIONAL_LIBRARIES.find(x=>x.id===id)??null}
export function getProfessionalFormula(libraryId,formulaId){return getProfessionalLibrary(libraryId)?.formulas.find(x=>x.id===formulaId)??null}
